//! The generated by-value wrappers that src/bindings does not call: the deprecated
//! `duckdb_value_*` result accessors, the deprecated chunk and Arrow readers, and the
//! `duckdb_string_t` helpers. Each wrapper must hand its struct through unchanged, so
//! each test compares the wrapper's output with the C function called directly.

use std::ffi::{CStr, CString};
use std::mem::MaybeUninit;
use std::ptr::null_mut;

use duckdb_bun_shim::by_value;
use libduckdb_sys as ffi;

/// An in-memory database and connection on the calling thread, closed on drop.
struct Db {
    database: ffi::duckdb_database,
    connection: ffi::duckdb_connection,
}

impl Db {
    fn open() -> Self {
        let mut database: ffi::duckdb_database = null_mut();
        let mut connection: ffi::duckdb_connection = null_mut();
        // SAFETY: valid out pointers; a null path opens an in-memory database.
        unsafe {
            assert_eq!(
                ffi::duckdb_open(std::ptr::null(), &mut database),
                ffi::DuckDBSuccess
            );
            assert_eq!(
                ffi::duckdb_connect(database, &mut connection),
                ffi::DuckDBSuccess
            );
        }
        Db {
            database,
            connection,
        }
    }

    /// Runs `sql` and returns its materialized result; the caller destroys it.
    fn query(&self, sql: &str) -> ffi::duckdb_result {
        let sql = CString::new(sql).unwrap();
        // SAFETY: live connection; a zeroed result is a valid out value.
        unsafe {
            let mut result: ffi::duckdb_result = std::mem::zeroed();
            let state = ffi::duckdb_query(self.connection, sql.as_ptr(), &mut result);
            assert_eq!(
                state,
                ffi::DuckDBSuccess,
                "{:?}",
                CStr::from_ptr(ffi::duckdb_result_error(&mut result))
            );
            result
        }
    }
}

impl Drop for Db {
    fn drop(&mut self) {
        // SAFETY: both handles are live and owned by this value.
        unsafe {
            ffi::duckdb_disconnect(&mut self.connection);
            ffi::duckdb_close(&mut self.database);
        }
    }
}

/// Calls a `dbs_value_*` wrapper with an out pointer and returns what it wrote.
fn read_out<T>(write: impl FnOnce(*mut T)) -> T {
    let mut out = MaybeUninit::<T>::uninit();
    write(out.as_mut_ptr());
    // SAFETY: every wrapper writes its out pointer before returning.
    unsafe { out.assume_init() }
}

#[test]
fn value_accessors_match_the_c_api() {
    let db = Db::open();
    let mut result = db.query(
        "SELECT DATE '2024-02-29' AS d, TIME '12:34:56.789' AS t, \
         TIMESTAMP '2024-02-29 12:34:56.789' AS ts, \
         INTERVAL '1 year 2 days 3 seconds' AS i, \
         170141183460469231731687303715884105727::HUGEINT AS h, \
         340282366920938463463374607431768211455::UHUGEINT AS u, \
         -12345.6789::DECIMAL(18, 4) AS dec, \
         'a string longer than twelve bytes' AS s, \
         '\\xAA\\xBB'::BLOB AS b",
    );
    let r: *mut ffi::duckdb_result = &mut result;
    // SAFETY: `r` is a live materialized result with one row of the columns above; every
    // string and blob the accessors return is freed with duckdb_free.
    unsafe {
        let date = read_out(|out| by_value::dbs_value_date(r, 0, 0, out));
        assert_eq!(date.days, ffi::duckdb_value_date(r, 0, 0).days);
        assert_eq!(date.days, 19782);

        let time = read_out(|out| by_value::dbs_value_time(r, 1, 0, out));
        assert_eq!(time.micros, ffi::duckdb_value_time(r, 1, 0).micros);
        assert_eq!(time.micros, 45_296_789_000);

        let timestamp = read_out(|out| by_value::dbs_value_timestamp(r, 2, 0, out));
        assert_eq!(
            timestamp.micros,
            ffi::duckdb_value_timestamp(r, 2, 0).micros
        );

        let interval = read_out(|out| by_value::dbs_value_interval(r, 3, 0, out));
        assert_eq!(
            (interval.months, interval.days, interval.micros),
            (12, 2, 3_000_000)
        );

        let hugeint = read_out(|out| by_value::dbs_value_hugeint(r, 4, 0, out));
        assert_eq!((hugeint.lower, hugeint.upper), (u64::MAX, i64::MAX));

        let uhugeint = read_out(|out| by_value::dbs_value_uhugeint(r, 5, 0, out));
        assert_eq!((uhugeint.lower, uhugeint.upper), (u64::MAX, u64::MAX));

        let decimal = read_out(|out| by_value::dbs_value_decimal(r, 6, 0, out));
        assert_eq!((decimal.width, decimal.scale), (18, 4));
        assert_eq!(decimal.value.lower as i64, -123_456_789);
        assert_eq!(decimal.value.upper, -1);

        // duckdb_value_string returns a copy the caller frees with duckdb_free.
        let string = read_out(|out| by_value::dbs_value_string(r, 7, 0, out));
        let bytes = std::slice::from_raw_parts(string.data.cast::<u8>(), string.size as usize);
        assert_eq!(bytes, b"a string longer than twelve bytes");
        ffi::duckdb_free(string.data.cast());

        // duckdb_value_string_internal points into the result, which owns it: the
        // C API spec says "The result must NOT be freed".
        let internal = read_out(|out| by_value::dbs_value_string_internal(r, 7, 0, out));
        let direct = ffi::duckdb_value_string_internal(r, 7, 0);
        assert_eq!((internal.data, internal.size), (direct.data, direct.size));
        let bytes = std::slice::from_raw_parts(internal.data.cast::<u8>(), internal.size as usize);
        assert_eq!(bytes, b"a string longer than twelve bytes");

        let blob = read_out(|out| by_value::dbs_value_blob(r, 8, 0, out));
        let bytes = std::slice::from_raw_parts(blob.data.cast::<u8>(), blob.size as usize);
        assert_eq!(bytes, [0xAA, 0xBB]);
        ffi::duckdb_free(blob.data);

        ffi::duckdb_destroy_result(r);
    }
}

#[test]
fn chunk_readers_return_every_row() {
    let db = Db::open();
    // SAFETY: each result is live until destroyed below; each chunk is destroyed once.
    unsafe {
        // duckdb_fetch_chunk reads a materialized result chunk by chunk, then returns null.
        let mut result = db.query("SELECT i FROM range(5000) t(i)");
        let mut rows = 0;
        loop {
            let mut chunk = by_value::dbs_fetch_chunk(&result);
            if chunk.is_null() {
                break;
            }
            rows += ffi::duckdb_data_chunk_get_size(chunk);
            ffi::duckdb_destroy_data_chunk(&mut chunk);
        }
        assert_eq!(rows, 5000);
        ffi::duckdb_destroy_result(&mut result);

        // duckdb_stream_fetch_chunk on a streaming result from a pending result.
        let sql = CString::new("SELECT i FROM range(5000) t(i)").unwrap();
        let mut prepared: ffi::duckdb_prepared_statement = null_mut();
        assert_eq!(
            ffi::duckdb_prepare(db.connection, sql.as_ptr(), &mut prepared),
            ffi::DuckDBSuccess
        );
        let mut pending: ffi::duckdb_pending_result = null_mut();
        assert_eq!(
            ffi::duckdb_pending_prepared_streaming(prepared, &mut pending),
            ffi::DuckDBSuccess
        );
        let mut result: ffi::duckdb_result = std::mem::zeroed();
        assert_eq!(
            ffi::duckdb_execute_pending(pending, &mut result),
            ffi::DuckDBSuccess
        );
        assert!(by_value::dbs_result_is_streaming(&result));
        let mut rows = 0;
        loop {
            let mut chunk = by_value::dbs_stream_fetch_chunk(&result);
            if chunk.is_null() {
                break;
            }
            rows += ffi::duckdb_data_chunk_get_size(chunk);
            ffi::duckdb_destroy_data_chunk(&mut chunk);
        }
        assert_eq!(rows, 5000);
        ffi::duckdb_destroy_result(&mut result);
        ffi::duckdb_destroy_pending(&mut pending);
        ffi::duckdb_destroy_prepare(&mut prepared);
    }
}

#[test]
fn result_arrow_array_exports_a_chunk() {
    let db = Db::open();
    // SAFETY: the result and chunk are live until destroyed below; the Arrow array is
    // released through its own release callback, as the Arrow C data interface requires.
    unsafe {
        let mut result = db.query("SELECT i FROM range(10) t(i)");
        let mut chunk = by_value::dbs_result_get_chunk(&result, 0);
        assert!(!chunk.is_null());
        let mut array = ffi::ArrowArray::empty();
        let mut out: ffi::duckdb_arrow_array = (&raw mut array).cast();
        by_value::dbs_result_arrow_array(&result, chunk, &mut out);
        assert_eq!(array.length, 10);
        if let Some(release) = array.release {
            release(&mut array);
        }
        ffi::duckdb_destroy_data_chunk(&mut chunk);
        ffi::duckdb_destroy_result(&mut result);
    }
}

#[test]
fn string_t_helpers_read_inlined_and_pointer_strings() {
    let db = Db::open();
    // SAFETY: the vector data holds two duckdb_string_t values that live as long as the chunk.
    unsafe {
        let mut result =
            db.query("SELECT * FROM (VALUES ('short'), ('a string longer than twelve')) t(s)");
        let mut chunk = by_value::dbs_result_get_chunk(&result, 0);
        let vector = ffi::duckdb_data_chunk_get_vector(chunk, 0);
        let strings = ffi::duckdb_vector_get_data(vector).cast::<ffi::duckdb_string_t>();
        let short = strings.add(0);
        let long = strings.add(1);
        assert!(by_value::dbs_string_is_inlined(short));
        assert!(!by_value::dbs_string_is_inlined(long));
        assert_eq!(by_value::dbs_string_t_length(short), 5);
        assert_eq!(by_value::dbs_string_t_length(long), 27);
        assert_eq!(
            by_value::dbs_string_t_length(long),
            ffi::duckdb_string_t_length(long.read())
        );
        ffi::duckdb_destroy_data_chunk(&mut chunk);
        ffi::duckdb_destroy_result(&mut result);
    }
}

#[test]
fn query_progress_of_an_idle_connection() {
    let db = Db::open();
    // SAFETY: live connection and a valid out pointer.
    let progress = read_out(|out| unsafe { by_value::dbs_query_progress(db.connection, out) });
    // SAFETY: as above.
    let direct = unsafe { ffi::duckdb_query_progress(db.connection) };
    assert_eq!(progress.percentage, direct.percentage);
    assert_eq!(progress.rows_processed, direct.rows_processed);
    assert_eq!(progress.total_rows_to_process, direct.total_rows_to_process);
}
